DO $$
DECLARE
  r record;
  n integer;
  total integer := 0;
BEGIN
  FOR r IN SELECT * FROM (VALUES
    ('ee9690ad-698e-45cb-ac9b-b5d20e47a267', '4054253e413df431fe097c713defcdf6', 'fc5fe7fcbc85cb3de7bc1f080fc27768', $q$<span style="font-weight: bold;">Ви здаєте в оренду й скутери?</span>$q$, $q$Так, здаємо в оренду й скутери.&nbsp;$q$),
    ('76ac05d1-65d6-426b-a8c3-da192e7fb82f', '8771c377a696d54c66f332607eacdfe8', '11ac8f874bdf3ff2b925dd070b9bfdcd', $q$Який мінімальний строк оренди?&nbsp;$q$, $q$Мінімальний строк оренди — <span style="font-weight: bold;">один день</span>.&nbsp;$q$),
    ('5a0578d6-f6c5-4ddf-91c7-aa5f1d41b8e6', 'f26ea0b60256043a30aca83e44d91246', 'f0d0c4fe314717d59a308b7d1322f85e', $q$Ви працюєте цілодобово?$q$, $q$У нас немає класичного графіка роботи, як у звичайного магазину. Ми працюємо на основі бронювань та індивідуальних домовленостей. Запити опрацьовуємо щодня з 8:00 до 19:00. Видача й повернення мотоциклів можливі будь-коли, навіть уночі. Під час оренди ми цілодобово на зв’язку з нашими клієнтами для вирішення непередбачених ситуацій.&nbsp;$q$),
    ('2eb52c53-9725-4fbf-bf6f-5163a690cb0c', 'bbf91d20ec244453b3f845b2a25343ba', '4f44edac5939edeb7ec33b5055f98f0c', $q$Скільки мотоциклів у вас є?$q$, $q$У нашому автопарку ти знайдеш понад 20 мотоциклів різних категорій (а також скутери). Пропозицію поступово розширюємо, актуальний огляд усієї техніки завжди знайдеш у каталозі (у розділі Обери мотоцикл).$q$),
    ('6a4ef36b-d2b7-4b4a-bc3b-82b3a643a941', 'e429833729e0762f7d1893fbd0a7cd9e', '72127c32c8f3b28032e80318959ad8b1', $q$Чи можу я під час повернення в іншому місці віддати мотоцикл раніше, ніж ми домовилися?$q$, $q$На домовлене місце ми виїжджаємо з Пельгржимова точно за погодженим часом, тому раніше повернення, на жаль, неможливе. Якщо твої плани зміняться, зв’яжися з нами — спробуємо час підлаштувати, але це залежить від нашої поточної завантаженості.$q$),
    ('9b388e3a-bf29-4760-a948-937e88a2f447', '0d8cb69ea84439fc338e8fe9d33670b2', 'c75960adf3e5c2cd51d2778a7c6e71fb', $q$Як заздалегідь треба повідомити про повернення в іншому місці?$q$, $q$Місце й час повернення ти вказуєш уже у формі бронювання.$q$),
    ('1e797601-b347-44e4-82a6-c7537273f218', '50d59f77523b05e3f7ea4909ac96c2b0', 'f218bc036b8b1caff1693d2397f2c071', $q$Що робити, якщо я запізнюся на місце повернення?$q$, $q$Зателефонуй нам, щойно зрозумієш, що не встигаєш вчасно. Домовимося — здебільшого ми тебе зачекаємо. Нам лише потрібно знати, на скільки ти запізнишся, щоб ми могли підлаштувати план дня.$q$),
    ('5444d2cf-0251-4a22-a373-0e361a36599f', '01378f6b0ebaca2cb258593a911e1a56', '11f66a67304a886685d9c913fae53214', $q$Як розраховується ціна повернення в іншому місці?$q$, $q$Ціна включає 500 Kč за завантаження, 500 Kč за розвантаження та 20 Kč за кожен кілометр відстані від місця повернення до прокату (туди й назад). Наприклад, за повернення за 50 км від Пельгржимова ти заплатиш 500 + 500 + (50 × 2 × 20) = 3 000 Kč.$q$),
    ('fdc85aa7-9aa6-4cab-a28b-6b0076cd10d9', '7b9a3d8eef596ac5800146ef9bfb54e6', '4b54e8eab708b78f2bfc2ddf03cc5181', $q$Чи плачу я за повернення в іншому місці окремо, чи це входить у ціну оренди?$q$, $q$Повернення в іншому місці — це додаткова послуга, яка оплачується окремо понад ціну оренди.$q$),
    ('65e534e5-11a1-4cc9-bab5-f6b01862611c', 'e36d67cffc7f93a356613832a010ce64', '7428e8d30af308cb85c8d57e9babb53f', $q$Що мені підготувати, коли ви приїдете по мотоцикл?$q$, $q$Підготуй ключі та все спорядження, яке ти в нас орендував/-ла. Більше нічого не потрібно.&nbsp;$q$),
    ('1d6a2118-149b-4215-9629-84bb4b61f8da', 'a52c01b3c7bafa5eacf919f3db415e03', '2a11002b63530ef31d9e86c6436a7fdb', $q$Чи можу я повернути мотоцикл до прокату раніше, ніж ми домовилися?$q$, $q$Так, мотоцикл можна повернути будь-коли протягом останнього дня оренди. Просто повідом нам, що приїдеш раніше. За раніше повернення ми нічого не доплачуємо.$q$),
    ('aa6d7e5a-526d-4147-a041-bc7972ef592a', 'bb9c68c48479fae3acf08902a07cccd3', 'c321f7778149d8c71921591e21652dee', $q$Що буде, якщо я не встигну повернути мотоцикл до прокату до опівночі останнього дня?$q$, $q$Якщо знаєш, що запізнишся, зв’яжися з нами якнайшвидше. Домовимося про рішення. У разі неповідомленого пізнього повернення діємо згідно з умовами договору оренди та Умовами надання послуг. Документи опубліковані на сайті в розділі Документи та інструкції.&nbsp;$q$),
    ('b0bc8012-76e6-4f62-bbe7-0a3ff171ec94', '9fe8f05a073e4a9c67878d3ce2d89cab', 'c938c86606944e702286ca4cf3b8c7c4', $q$Як відбувається огляд мотоцикла під час повернення в прокаті?$q$, $q$Ми разом переглянемо стан мотоцикла й спорядження. Якщо все гаразд, приймемо ключі та спорядження, і ти можеш іти. Усе це займе кілька хвилин.$q$),
    ('3981c695-81fb-43db-9146-0c9e0876c7cf', '8b87c607587dce79200cb2a32f1cd9ed', 'cfe8537cf84f5d066b5de98d13e6948b', $q$<span style="font-weight: bold;">До котрої години треба повернути мотоцикл?</span>$q$, $q$Повернути мотоцикл можна будь-коли протягом останнього дня оренди — <span style="font-weight: bold;">не пізніше опівночі</span>. <span style="font-weight: bold;">Орієнтовний час повернення, будь ласка, вкажи прямо у формі бронювання</span>, щоб ми могли краще спланувати день. Або вже під час оренди можеш змінити час повернення в розділі Змінити бронювання прямо на сайті.&nbsp;<div><br></div><div>Якщо повертаєш мотоцикл в іншому місці, обов’язковим є домовлений час, який ти вибрав/-ла у формі бронювання.</div>$q$),
    ('5c26fb3a-a29e-453a-8474-152d4ee61246', '61306c1c76dea6d79e8482eba83d3f3e', 'dc5983798787ab38e196a993546f6faf', $q$Що робити, якщо я не встигаю на домовлений час отримання?$q$, $q$Якнайшвидше зателефонуй нам, і ми домовимося про рішення.$q$),
    ('b4bf8554-35d6-4bcc-a205-1d783d705615', '72e3c1a7d32e90eeb453db23606bfd20', '8a23fde12947f6f059560b5612f8df50', $q$З якого віку дитина може їздити на мотоциклі?$q$, $q$Єдиного віку для всіх немає — <span style="font-weight: bold;">усе залежить від фізичної </span>та <span style="font-weight: bold;">психічної зрілості дитини</span>.&nbsp;<div><br><div>Для найменших і найспритніших охочих <span style="font-weight: bold;">від 3</span>–<span style="font-weight: bold;">4</span> <span style="font-weight: bold;">років </span>у нас є&nbsp;<span style="font-weight: bold;">Yamaha PW 50</span>.&nbsp;</div><div><br></div><div>Від <span style="font-weight: bold;">5</span>–<span style="font-weight: bold;">6</span> <span style="font-weight: bold;">років </span>можна орендувати мотоцикл <span style="font-weight: bold;">KTM 50</span> <span style="font-weight: bold;">SX Replica</span>.&nbsp;</div><div><br></div><div>Для вправних старших райдерів віком <span style="font-weight: bold;">9</span>–<span style="font-weight: bold;">12 років</span>, які вже мають досвід їзди, у нас є <span style="font-weight: bold;">Husqvarna TC 65</span>.&nbsp;</div><div><br></div><div>Уся інформація доступна в Каталозі мотоциклів, а також у статті «Підтримай мрію свого маленького мотоцикліста» в нашому блозі. Якщо матимеш запитання, охоче на них відповімо.&nbsp;</div></div>$q$),
    ('333ae882-1e32-4d8e-818e-027e48af5c35', 'e23244ff0f11bcf865d03ab359107f20', 'adeebc37e42123f99866b0829e27fd1f', $q$Як відбувається отримання мотоцикла в прокаті?$q$, $q$Привітно й без стресу. Ми тебе зустрінемо, разом оглянемо мотоцикл, перевіримо твої документи (ID-картку та посвідчення водія), ти забереш спорядження, яке вибрав/-ла під час бронювання, ми підпишемо акт приймання-передачі, ти отримаєш ключі й можеш вирушати.&nbsp;<div>Автомобіль можеш залишити в нас на парковці, а особисті речі — у шафці, якщо буде потрібно.&nbsp;</div>$q$),
    ('e18a59ca-f1f5-42ff-9f06-522af9b08b65', '9ab6009967d80271a3fb167f1be911e2', 'a6aaae9a42bf2a049c69fe425967aaad', $q$Чи можна орендувати мотоцикл з іноземним посвідченням водія?$q$, $q$<p>Так, це не проблема. Потрібне лише чинне посвідчення водія відповідної категорії (A/A2) і документ, що посвідчує особу (ID-картка або паспорт).&nbsp;</p>
<h3></h3>$q$),
    ('06e44d78-8b32-4b96-9f54-339ad771f754', '7294ebc87dd64bd039222b1b4dccbb2c', '0b55131d1ac089c6708c62bf8ac48de9', $q$Чи можу я керувати Yamaha Niken із посвідченням водія категорії B?$q$, $q$У техпаспорті вказано категорію&nbsp; L3e-A3, тобто потужний одноколійний мотоцикл, тож слід врахувати, що для Niken потрібне посвідчення водія&nbsp; категорії A. Самої категорії B недостатньо: хоча фізично в нього 3 колеса, за документами — лише 2.$q$),
    ('16fde840-124b-4d9b-9b28-8fef51f6cd63', '8d8a3beab1013d5bc3bf126efb24484d', '496dff270b2c86db72d702e8aaa27233', $q$Ви також здаєте дощовики?&nbsp;$q$, $q$Так, здаємо. Дощове спорядження ми охоче надамо безкоштовно — на запит прямо в прокаті, залежно від поточної завантаженості. Маємо дощові бахіли та комплект «плащ» і штани.&nbsp;<div><br></div><div>Дощовики видаємо лише у філії з персоналом у Mezná біля Пельгржимова. У філії самообслуговування у Velké Němčice їх немає — там можна взяти лише шолом, куртку із захистом спини, штани, рукавиці, балаклаву й черевики.</div>$q$),
    ('f2c036d1-4aec-414c-b953-41d379a43277', '9fbf4b26e0c14352eba38d5b8c4e9b5d', 'b72123be099bcfdbc91f74dc800783a4', $q$Чи можна у вас орендувати й багажну сітку?$q$, $q$Так, багажну сітку ми теж охоче надамо. На запит прямо в мотопрокаті. Оренда сітки безкоштовна.&nbsp;$q$),
    ('753cbff4-046c-4807-abf3-018a1e201766', 'b77450b076e3a38bd7461c3d253506ee', 'c5a97838cc1fa593cf479968568ddb0e', $q$З якого віку й з яким досвідом можна у вас орендувати мотоцикл?$q$, $q$<p>Достатньо мати <strong>чинне посвідчення водія відповідної категорії</strong> (A2 або A залежно від мотоцикла) та чинну ID-картку або паспорт. <strong>Мінімального досвіду не вимагаємо</strong> — здамо й новачкові.<strong>&nbsp;Мінімальний вік орендаря — 18 років.&nbsp;</strong>У разі дитячих мотоциклів орендарем завжди є батько, мати або законний представник старше 18 років, який несе за дитину повну відповідальність.</p>$q$),
    ('7d72e4b0-e2ff-4713-99a7-6bdaf44d924b', 'a2b6b61d9dddaf431d37976ed88ac6b8', 'f4f061fb3f3ca8ed85be0b594b31b859', $q$Чи можна на вашому мотоциклі пройти базовий курс мотошколи?&nbsp;$q$, $q$Так, якщо в тебе є чинне посвідчення водія потрібної категорії, на наших мотоциклах можна пройти базовий курс мотошколи (без їзди на задньому колесі, пробуксовки шин тощо).$q$),
    ('a2e964db-1263-40cb-86ff-6420c0841e56', 'c2a41bf635844577c8747b5a9ae65fee', '99c049d5c801354ac0ae7f89c5491da1', $q$У вас є якийсь ліміт кілометрів на день?&nbsp;$q$, $q$Ні, <span style="font-weight: bold;">пробіг </span>ми жодним чином <span style="font-weight: bold;">не обмежуємо</span> —&nbsp; лише від тебе залежить, скільки проїдеш.&nbsp;$q$),
    ('a278501f-331d-4b53-a298-22eba57451ea', 'ab6ece8426ff26583398ac62ae964b64', '4b71732ad28435eb06758956a0b03e1d', $q$Що робити, якщо мотоцикл дорогою зламається або станеться аварія?$q$, $q$<p>Головне — спокій і безпека понад усе. У разі будь-якої поломки, аварії, пошкодження чи навіть підозри на несправність <strong>негайно зателефонуй нам</strong> і дій за нашими вказівками. Будь ласка, не виконуй самостійно жодних ремонтів чи сервісних втручань. Контакт асистанс-служби є також у комплекті мотоцикла.</p>
<p>У разі дорожньо-транспортної пригоди або викрадення ти зобов’язаний/-а <strong>викликати поліцію Чеської Республіки</strong> (за кордоном — місцеву поліцію), заповнити й підписати <strong>протокол про ДТП</strong> та співпрацювати під час розслідування. Поліцію викликай завжди, коли цього вимагає закон, — зокрема в разі травм, шкоди понад 100 000 Kč, шкоди чужому майну або коли учасники не дійдуть згоди. У разі дрібних пошкоджень, які за законом не є ДТП, достатньо зв’язатися з нами й діяти за домовленістю.</p>
<p>Як ми вирішимо ситуацію, залежить від масштабу несправності та місця, де ти перебуваєш, — домовимося про ремонт, перевезення або інше рішення. Якщо з твоєї вини станеться аварія, яка унеможливить подальшу їзду, оренда на цьому закінчується. Якщо аварію спричинив не ти, домовимося про справедливу компенсацію з огляду на решту строку оренди.</p>$q$),
    ('92fb7f7a-f82b-415c-8d8f-0dc012899b73', '999b9c5e9e53fc893a8cc97bb1c7da47', '7a3537e9187ec5cc69ef40a6e78f2d2c', $q$Чи можна взяти пасажира?&nbsp;$q$, $q$<p>Так, якщо мотоцикл розрахований на двох осіб (більшість наших туристичних, нейкед- і супермото-моделей). Спорядження для водія завжди входить у ціну; <strong>спорядження для пасажира легко дозамовиш</strong> як додаткову послугу прямо у формі бронювання. Дитячі мотоцикли призначені лише для одного райдера.</p>$q$),
    ('9e5a0b6a-262b-4029-8349-0542310a879c', 'dd5258d992a33cb18a40d04991c5e353', '8c6a18af9942f967bedcce6becb3ac34', $q$<strong>Ви пропонуєте інтеркоми?</strong><br>$q$, $q$<p>Інтеркомів поки що в пропозиції немає. Ми працюємо над розширенням спорядження, тож у майбутньому вони заплановані.&nbsp;</p>$q$),
    ('8f8eb104-3f74-4d0d-82cc-271c59ac3d70', 'd82b9de980735843df823a3c0ea7f626', '30096f8f7c1982a9ab3d3e8cb43a95b9', $q$Чи входить у ціну спорядження для пасажира?$q$, $q$Спорядження для пасажира не входить у базову ціну, але його легко дозамовити як додаткову послугу прямо у формі бронювання.$q$),
    ('43a6ee13-9e6c-4cf2-b4b0-5bdeb96259e4', 'c1212309fe4797115d99130d58047af2', 'ba9ecfc517095056190c543622066fd7', $q$Чи потрібна застава?$q$, $q$Ні. Мотоцикли здаємо в оренду <strong>без застави</strong> й без прихованих платежів.$q$),
    ('732b6abe-a788-4fa5-b3a2-bd0ddfc371f0', '770e7d2c6edb8e015c52fe1cb6b10c93', '96399aea1484068e218b4f2dd151d797', $q$Які документи мені потрібні?$q$, $q$<strong>ID-картка/паспорт</strong> і <strong>посвідчення водія</strong> відповідної категорії (A/A2 залежно від мотоцикла).$q$),
    ('21046767-7631-4fba-aced-30f7f639f3b1', '2ab6f4f7329d8c5ca5d40066a4b28d63', 'bf89cf34f78d0a3c00b9f51439ed2138', $q$Що буде, якщо ви не зможете видати мотоцикл?$q$, $q$У такому разі ми негайно зв’яжемося з тобою й запропонуємо найкраще можливе рішення — інший мотоцикл або інший термін. А на знак вибачення отримаєш знижку на наступне бронювання.$q$),
    ('c0f9f534-401c-462b-af49-04ca02b73f18', 'c07c80cf3813ae36dcb781637eac20ee', 'a05347cd9a147d4a43db888648bbaada', $q$Як вибрати правильний розмір спорядження?$q$, $q$Розміри спорядження вказуєш прямо у формі бронювання. Якщо не впевнений/-а, домовся з нами про візит до прокату — можеш заздалегідь приїхати приміряти мотоодяг і черевики. Наявність конкретних розмірів залежить від поточної завантаженості прокату.&nbsp;$q$)
  ) AS v(id, q_md5, a_md5, q_uk, a_uk) LOOP
    UPDATE public.faq_items
       SET translations = COALESCE(translations, '{}'::jsonb) || jsonb_build_object('uk', jsonb_build_object('question', r.q_uk, 'answer', r.a_uk))
     WHERE id = r.id::uuid AND md5(question) = r.q_md5 AND md5(answer) = r.a_md5
       AND NOT (COALESCE(translations, '{}'::jsonb) ? 'uk');
    GET DIAGNOSTICS n = ROW_COUNT;
    total := total + n;
    IF n = 0 THEN RAISE NOTICE 'faq uk: beze změny % (uk už je, nebo se čeština změnila)', r.id; END IF;
  END LOOP;
  RAISE NOTICE 'faq uk (část 1): doplněno % překladů', total;
END $$;
